(7488493, 1191946, 173297, '<td valign="top">Thx to everyone for liking this. This is a mountain feature i found while on my travel to Northern Pakistan.</td>', 'Thx to everyone for liking this. This is a mountain feature i found while on my travel to Northern Pakistan.', '2016-12-23 01:54:54.000000', NULL, 0),
(7488669, 1191946, 173297, '<td valign="top">The picture was original, shot from my Nikon during the dates u mentioned and i uploaded from my cell as the northern pak has no wifi so i couldnt upload from my laptop.. i uploaded all my north pak pics on fb and then used my cell and data package to upload onto ur site.. there is no other way for me to make u believe.. disqualify as u may  but i believe its just discrimination. Im a semi  professional photographer here in pak and use my skills to promote pakistan and its natural beauty.</td>', 'The picture was original, shot from my Nikon during the dates u mentioned and i uploaded from my cell as the northern pak has no wifi so i couldnt upload from my laptop.. i uploaded all my north pak pics on fb and then used my cell and data package to upload onto ur site.. there is no other way for me to make u believe.. disqualify as u may  but i believe its just discrimination. Im a semi  professional photographer here in pak and use my skills to promote pakistan and its natural beauty.', '2016-12-24 23:37:43.000000', NULL, 0),
(7488671, 1191946, 30861, '<td valign="top">It''s not a matter of whether we believe you or not; this is just an ironclad rule that''s been in place as long as this challenge site has been in existence; without a valid original with full EXIF data we cannot validate a winner. Without this rule we''d have people going into their archives for images that suit every challenge, and the whole point of DPC is to shoot FOR a challenge.</td>', 'It''s not a matter of whether we believe you or not; this is just an ironclad rule that''s been in place as long as this challenge site has been in existence; without a valid original with full EXIF data we cannot validate a winner. Without this rule we''d have people going into their archives for images that suit every challenge, and the whole point of DPC is to shoot FOR a challenge.', '2016-12-24 23:59:58.000000', NULL, 0),
(7488688, 1191590, 25024, '<td valign="top">Hey Marcel, well done! I''ve only just seen your latest addition to your ever-growing ribbon collection and what a worthy addition it is, great use of natural lighting with a humorous feel to it which is always welcome. I''m proud of you, keep up the good work...</td>', 'Hey Marcel, well done! I''ve only just seen your latest addition to your ever-growing ribbon collection and what a worthy addition it is, great use of natural lighting with a humorous feel to it which is always welcome. I''m proud of you, keep up the good work...', '2016-12-25 06:46:05.000000', NULL, 0),
(7488849, 1191939, 108040, '<td valign="top">Thanks.</td>', 'Thanks.', '2016-12-26 18:06:32.000000', NULL, 0),
